#!/usr/bin/env python3
# patch-158-G6: asset-card inner padding (parts + work order)
"""
Fix the flush-to-edge problem inside asset cards: the per-asset
Parts and Work order collapsibles had no horizontal padding on their
head or body, so labels, inputs, and form fields touched the asset
card's border directly. The services section already had 18px
horizontal padding; this brings parts + work-order to match so
all three nested sections align vertically.

  - .ma-asset-parts-head: padding 10px 18px 8px (was 10px 0 8px)
  - .ma-asset-parts-body: padding 4px 18px 12px (was top/bottom only)
  - .ma-asset-wo-body:    padding 4px 18px 12px (was top/bottom only)

Single-file view patch. CSS-only. No backend changes.
"""
